function showCard() {
  if (queue.length === 0) {
    document.getElementById('card').innerHTML = '<div class="done">🎉 本轮复习完成！刷新页面开始新一轮。</div>';
    document.getElementById('buttons').classList.add('hidden');
    document.getElementById('hint').textContent = '';
    return;
  }
  currentIdx = queue.shift();
  flipped = false;
  document.getElementById('label').textContent = '问题';
  document.getElementById('content').innerHTML = CARDS[currentIdx].q;
  document.getElementById('source').textContent = '';
  document.getElementById('buttons').classList.add('hidden');
  document.getElementById('hint').textContent = '点击卡片翻转 · 空格键翻转 · ←→ 键评分';
}

function flip() {
  if (flipped) return;
  flipped = true;
  document.getElementById('label').textContent = '答案';
  document.getElementById('content').innerHTML = CARDS[currentIdx].a.replace(/\n/g, '<br>');
  document.getElementById('source').textContent = '来源：' + CARDS[currentIdx].source;
  document.getElementById('buttons').classList.remove('hidden');
  document.getElementById('hint').textContent = '';
}

