args.new_str:
function submit() {
  const userText = document.getElementById('userInput').value.trim();
  if (!userText) {
    document.getElementById('userInput').placeholder = '至少写几个关键词再提交...';
    return;
  }
  // 记录历史
  const key = String(currentIdx);
  if (!history[key]) history[key] = [];
  history[key].push({ text: userText, time: new Date().toLocaleString('zh-CN') });
  saveHistory();

  document.getElementById('inputArea').style.display = 'none';
  document.getElementById('answerBox').style.display = 'block';
  document.getElementById('answerContent').innerHTML = CARDS[currentIdx].a.replace(/\n/g, '<br>');
  document.getElementById('yourAnswer').textContent = userText;

  // 显示历史记录
  const histList = history[key];
  let histHtml = '';
  if (histList.length > 1) {
    histHtml = '<div style="margin-top:0.8em;padding-top:0.8em;border-top:1px solid #e0e0e0;font-size:12px;color:#999;">\u5386\u53f2\u56de\u7b54\uff1a';
    for (let i = histList.length - 2; i >= Math.max(0, histList.length - 4); i--) {
      histHtml += '<div style="margin-top:0.3em;color:#777;">' + histList[i].time + '\uff1a' + histList[i].text.replace(/</g,'&lt;') + '</div>';
    }
    histHtml += '</div>';
  }
  document.getElementById('historyArea').innerHTML = histHtml;

  document.getElementById('sourceText').textContent = '\u6765\u6e90\uff1a' + CARDS[currentIdx].source;
  document.getElementById('buttons').style.display = 'flex';
}

