const API_BASE = 'https://flashcards.lqita507.workers.dev';
const AUTH_TOKEN = '233996';

async function loadFromCloud() {
  try {
    const res = await fetch(API_BASE + '/api/load');
    const data = await res.json();
    if (data && data.weights) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data.weights));
      if (data.history) localStorage.setItem(HISTORY_KEY, JSON.stringify(data.history));
      return data;
    }
  } catch(e) { console.log('Cloud load failed, using local'); }
  return null;
}

async function saveToCloud() {
  try {
    await fetch(API_BASE + '/api/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + AUTH_TOKEN },
      body: JSON.stringify({ weights, history })
    });
  } catch(e) { console.log('Cloud save failed'); }
}

function loadWeights() {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved) return JSON.parse(saved);
  return CARDS.map(() => 0);
}
function saveWeights() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(weights));
  saveToCloud();
}

function loadHistory() {
  const saved = localStorage.getItem(HISTORY_KEY);
  if (saved) return JSON.parse(saved);
  return {};
}
function saveHistory() {
  localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
}

let weights = loadWeights();
while (weights.length < CARDS.length) weights.push(0);
let history = loadHistory();

// 启动时从云端同步
loadFromCloud().then(data => {
  if (data && data.weights) {
    weights = data.weights;
    while (weights.length < CARDS.length) weights.push(0);
    if (data.history) history = data.history;
    buildQueue(); updateStats(); showCard();
  }
});

