content.Text:
}

let weights = loadWeights();
while (weights.length < CARDS.length) weights.push(0);
let history = loadHistory();

// 启动时从云端同步
loadFromCloud().then(data => {
  if (data && data.weights) {
    weights = data.weights;
    while (weights.length < CARDS.length) weights.push(0);
    if (data.history) history = data.history;
    buildQueue(); updateStats(); showCard();
  }
});

let queue = [];
let currentIdx = -1;
let activeFilter = null; // null = 全部

function getSources() {
  return [...new Set(CARDS.map(c => c.source))];
}

function renderFilters() {
  const sources = getSources();
  let html = '<button class="filter-btn active" onclick="setFilter(null)">全部</button>';
  sources.forEach(s => {
    const label = s.replace(/^[^_]+_\d+_/, '');
    html += `<button class="filter-btn" onclick="setFilter('${s}')">${label}</button>`;
  });
  document.getElementById('filters').innerHTML = html;
}

function setFilter(source) {
  activeFilter = source;
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.classList.remove('active');
    if ((!source && btn.textContent === '全部') || btn.getAttribute('onclick').includes(source)) {
      btn.classList.add('active');
    }
  });
  buildQueue();
  updateStats();
  showCard();
}

function buildQueue() {
  queue = CARDS.map((_, i) => i);
  if (activeFilter) {
    queue = queue.filter(i => CARDS[i].source === activeFilter);
  }
  queue.sort((a, b) => {
    if (weights[b] !== weights[a]) return weights[b] - weights[a];
    return Math.random() - 0.5;
  });
}

function updateStats() {
  const pool = activeFilter ? CARDS.map((_, i) => i).filter(i => CARDS[i].source === activeFilter) : CARDS.map((_, i) => i);
  const total = pool.length;
  const mastered = pool.filter(i => weights[i] <= -2).length;
  const struggling = pool.filter(i => weights[i] >= 2).length;
  document.getElementById('stats').textContent =
    `共 ${total} 张 \u00b7 已掌握 ${mastered} \u00b7 需加强 ${struggling}`;
}

function showCard() {
  if (queue.length === 0) {
    document.getElementById('card').innerHTML = '<div class="done">\ud83c\udf89 本轮复习完成！刷新页面开始新一轮。</div>';
    document.getElementById('inputArea').style.display = 'none';
    document.getElementById('answerBox').style.display = 'none';
    document.getElementById('buttons').style.display = 'none';
    return;
  }
  currentIdx = queue.shift();
  document.getElementById('question').textContent = CARDS[currentIdx].q;
  document.getElementById('hint').textContent = '\ud83d\udca1 ' + CARDS[currentIdx].hint;
  document.getElementById('inputArea').style.display = 'block';
  document.getElementById('answerBox').style.display = 'none';
  document.getElementById('buttons').style.display = 'none';
  document.getElementById('userInput').value = '';
  document.getElementById('userInput').focus();
}

function submit() {
  const userText = document.getElementById('userInput').value.trim();
  if (!userText) {
    document.getElementById('userInput').placeholder = '至少写几个关键词再提交...';
    return;
  }
  // 记录历史
  const key = String(currentIdx);
  if (!history[key]) history[key] = [];
  history[key].push({ text: userText, time: new Date().toLocaleString('zh-CN') });
  saveHistory();

  document.getElementById('inputArea').style.display = 'none';
  document.getElementById('answerBox').style.display = 'block';
  document.getElementById('answerContent').innerHTML = CARDS[currentIdx].a.replace(/\n/g, '<br>');
  document.getElementById('yourAnswer').textContent = userText;

  // 显示历史记录
  const histList = history[key];
  let histHtml = '';
  if (histList.length > 1) {
    histHtml = '<div style="margin-top:0.8em;padding-top:0.8em;border-top:1px solid #e0e0e0;font-size:12px;color:#999;">\u5386\u53f2\u56de\u7b54\uff1a';
    for (let i = histList.length - 2; i >= Math.max(0, histList.length - 4); i--) {
      histHtml += '<div style="margin-top:0.3em;color:#777;">' + histList[i].time + '\uff1a' + histList[i].text.replace(/</g,'&lt;') + '</div>';
    }
    histHtml += '</div>';
  }
  document.getElementById('historyArea').innerHTML = histHtml;

  document.getElementById('sourceText').textContent = '\u6765\u6e90\uff1a' + CARDS[currentIdx].source;
  document.getElementById('buttons').style.display = 'flex';
}

function answer(got) {
  if (got) {
    weights[currentIdx] = Math.max(weights[currentIdx] - 1, -3);
  } else {
    weights[currentIdx] = Math.min(weights[currentIdx] + 1, 5);
  }
  saveWeights();
  updateStats();
  showCard();
}

// 快捷键：Enter提交，← →评分
document.addEventListener('keydown', (e) => {
  if (e.code === 'Enter' && !e.shiftKey && document.getElementById('inputArea').style.display !== 'none') {
    e.preventDefault();
    submit();
  }
  if (document.getElementById('buttons').style.display === 'flex') {
    if (e.code === 'ArrowLeft') answer(false);
    if (e.code === 'ArrowRight') answer(true);
  }
});

function resetWeights() {
  if (confirm('\u786e\u5b9a\u91cd\u7f6e\u6240\u6709\u6743\u91cd\uff1f')) {
    weights = CARDS.map(() => 0);
    saveWeights(); buildQueue(); updateStats(); showCard();
  }
}
function exportData() {
  const blob = new Blob([JSON.stringify({ cards: CARDS, weights }, null, 2)], { type: 'application/json' });
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = 'flashcards_backup.json'; a.click();
}
function importData(event) {
  const file = event.target.files[0]; if (!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    const data = JSON.parse(e.target.result);
    if (data.weights) { weights = data.weights; while (weights.length < CARDS.length) weights.push(0); saveWeights(); buildQueue(); updateStats(); showCard(); }
  };
  reader.readAsText(file);
}

buildQueue(); updateStats(); showCard();
</script>
</body>
</html>

