let activeFilter = null; // null = 全部
let filterType = 'source'; // 'source' or 'topic'

function getSources() {
  return [...new Set(CARDS.map(c => c.source))];
}

function getTopics() {
  return [...new Set(CARDS.map(c => c.topic))];
}

function renderFilters() {
  const sources = getSources();
  const topics = getTopics();
  let html = '<button class="filter-btn active" onclick="setFilter(null)">全部</button>';
  html += '<span style="color:#ccc;margin:0 0.3em;">|</span>';
  topics.forEach(t => {
    html += `<button class="filter-btn" onclick="setFilter('${t}','topic')">${t}</button>`;
  });
  html += '<span style="color:#ccc;margin:0 0.3em;">|</span>';
  sources.forEach(s => {
    const label = s.replace(/^[^_]+_\d+_/, '');
    html += `<button class="filter-btn" onclick="setFilter('${s}','source')">${label}</button>`;
  });
  document.getElementById('filters').innerHTML = html;
}

function setFilter(value, type) {
  activeFilter = value;
  filterType = type || 'source';
  document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));
  // 高亮当前按钮
  document.querySelectorAll('.filter-btn').forEach(btn => {
    if (!value && btn.textContent === '全部') btn.classList.add('active');
    else if (btn.getAttribute('onclick') && btn.getAttribute('onclick').includes(`'${value}'`)) btn.classList.add('active');
  });
  buildQueue();
  updateStats();
  showCard();
}

